export const BEHAVIOR_ELEMENT_REFERENCES: Record<string, { title: string; chapter: string; body: string; example: string }> = Object.fromEntries([
  ['activity:action', 'Action', 'activity-diagrams', 'A modeled unit of work. Inspect name and optional called behavior; typed input/output pins describe object-transfer endpoints.', 'Place Validate request after Initial. Add reading as a typed input pin if validation consumes that object, then choose the supported called behavior where available.'],
  ['activity:initial', 'Initial Node', 'activity-diagrams', 'The starting control node of the modeled activity flow. Its outgoing edge introduces the first action path.', 'Place Initial and connect it to Receive request using Control Flow. Inspect initial-node diagnostics rather than assuming the leftmost action starts first.'],
  ['activity:activityFinal', 'Activity Final', 'activity-diagrams', 'Terminates the modeled Activity, including its concurrent activity flows. It differs from a Flow Final.', 'Connect the completed operation path to Activity Final when the entire activity should finish, then review any parallel branches that this final node would terminate.'],
  ['activity:flowFinal', 'Flow Final', 'activity-diagrams', 'Ends the arriving flow without declaring that all other activity flows terminate.', 'After a Fork, end an optional logging branch at Flow Final while the main branch continues. Use Activity Final only where the entire activity should terminate.'],
  ['activity:decision', 'Decision', 'activity-diagrams', 'Routes a token through a guarded alternative. Inspect outgoing guards and the supported else path.', 'After Validate create a Decision with [valid] to Process and [else] to Reject. Avoid two simultaneously true alternatives unless that ambiguity is intended and supported.'],
  ['activity:merge', 'Merge', 'activity-diagrams', 'Recombines alternative paths without synchronization. A Merge is not a Join.', 'Route accepted and recovered alternatives into Merge, then continue to Finish. If both paths run concurrently and must complete, use Join semantics instead.'],
  ['activity:fork', 'Fork', 'activity-diagrams', 'Splits a control path into modeled concurrent branches. Review branch endpoints and later synchronization.', 'Fork an accepted path into Process and Log. Connect each outgoing Control Flow explicitly; placing two actions beside one another does not create concurrency.'],
  ['activity:join', 'Join', 'activity-diagrams', 'Synchronizes modeled concurrent incoming paths before continuing. Its meaning differs from merging alternatives.', 'Join Process and Log after a Fork before Finish. Review that both branches can reach the Join; a mutually exclusive Decision path should not be mistaken for parallel execution.'],
  ['activity:objectNode', 'Object Node', 'activity-diagrams', 'A typed object/data holder in an activity. Compatible Object Flow transfers modeled values through it.', 'Create reading: SensorReading between a producer output pin and consumer input pin. Select the same compatible classifier and inspect the object-flow endpoint diagnostics.'],
  ['activity:activityParameterNode', 'Activity Parameter', 'activity-diagrams', 'A boundary value associated with an Activity parameter, including its type and direction.', 'Create an input request parameter and its Activity Parameter node. Connect compatible object endpoints inside the activity and inspect the parameter direction rather than using a control edge for data.'],
  ['activity:pin', 'Input and Output Pin', 'activity-diagrams', 'An owned action endpoint with type and direction. Pins are data endpoints rather than independent control actions.', 'Create an output reading pin on Acquire and an input reading pin on Validate. Select compatible types, connect Object Flow and inspect any direction mismatch diagnostic.'],
  ['sequence:lifeline', 'Lifeline', 'sequence-diagrams', 'A participant in an Interaction, optionally representing a compatible existing element or property usage.', 'Add sensor: Sensor and controller: Controller lifelines from existing candidates. Choose sender and receiver using their identities; renaming a participant must not create another definition.'],
  ['sequence:message', 'Message', 'sequence-diagrams', 'An ordered interaction between participants. Sort, signature, arguments, connector reference and call/reply association determine its modeled meaning.', 'Create Controller → Sensor read() as a synchronous call and add its matching reply. Inspect the receiving operation and parameter arguments before trying a supported runtime path.'],
  ['sequence:fragment', 'Combined Fragment', 'sequence-diagrams', 'A frame with an operator, covered lifelines and operands. Stored semantic operators can exceed the supported execution/code-generation subset.', 'Add an alt frame covering Controller and Sensor. Put [ready] messages in one operand and [else] in the other; inspect membership and guard diagnostics after moving the frame.'],
  ['sequence:operand', 'Interaction Operand', 'sequence-diagrams', 'A guarded region inside a Combined Fragment. Operand membership assigns messages to a branch or iteration region.', 'In an alt fragment add [ready] and [else] operands, then inspect which message IDs each covers. Resizing a frame does not by itself establish the intended execution conditions.'],
  ['sequence:ref', 'Interaction Use (ref)', 'sequence-diagrams', 'References an existing Interaction using covered lifelines, arguments and its order relative to messages.', 'Create a ref frame to an existing Initialize interaction, select covered participants and place it before start(). Inspect the referenced identity and runtime invocation limits.'],
  ['sequence:invariant', 'State Invariant', 'sequence-diagrams', 'A modeled assertion or referenced state at an interaction position. It does not automatically activate a State Machine.', 'Add a state invariant [Ready] on Controller before start(). Select a supported state reference if applicable and review the anchored message order and validation diagnostics.'],
  ['sequence:time', 'Time and Duration Constraint', 'sequence-diagrams', 'An assertion about message occurrence time or elapsed duration, with supported anchors and an expression.', 'Attach a duration constraint between request and reply to describe an intended 100 ms bound. Review anchors and expression; collect actual timing evidence in the executable test workflow.'],
  ['usecase:actor', 'Actor', 'use-case-diagrams', 'An external role interacting with goals inside the subject. Actors have identity and may specialize compatible actors.', 'Place Operator outside Pump system and associate it with Start Pump. If MaintenanceOperator specializes Operator, direct Generalization toward Operator and inspect the actor relationship.'],
  ['usecase:subject', 'Subject Boundary', 'use-case-diagrams', 'The modeled system scope containing its goals. It separates the system under discussion from external roles.', 'Name the boundary Pump system and place Start Pump inside it while Operator remains outside. This communicates scope rather than defining a solver or deployment boundary.'],
  ['usecase:extension', 'Extension Point', 'use-case-diagrams', 'A named point on the base Use Case used by an Extend relationship and its optional condition.', 'Add pricing to Checkout, then use it as the extension point for Apply Coupon → Checkout with condition [coupon supplied]. Inspect that the point belongs to the base goal.'],
  ['state:state', 'State', 'state-machine-fundamentals', 'An active behavior configuration with supported entry, do and exit actions, transitions and hierarchy.', 'Create Idle and Running. Mark the starting state explicitly, add a [request] transition and inspect the active configuration and action trace across simulation ticks.'],
  ['state:junction', 'Junction', 'state-machine-transitions', 'A supported transition-routing node for guarded paths. It is not a state with independently retained active behavior.', 'Add a Junction from the canvas context menu and connect an incoming transition and supported outgoing guards. Inspect routing diagnostics and compare the selected branch with the simulation trace.'],
  ['state:xbridges', 'X-Bridges State', 'state-machine-fundamentals', 'A chart state associated with supported embedded control behavior. Configure the control model and its chart execution context.', 'Add an X-Bridges State through the State Machine context menu, configure its embedded signal blocks and supported interfaces, then review chart and control traces before generating code.'],
].map(([id, title, chapter, body, example]) => [id, { title, chapter, body, example }]));

function schematic(labels: string[], caption: string, edgeLabel = 'reference / context'): HelpDiagram {
  return { kind: 'blocks', nodes: labels.map((label, i) => ({ id: `n${i}`, label })),
    edges: labels.slice(1).map((_, i) => ({ from: `n${i}`, to: `n${i + 1}`, label: edgeLabel, notation: 'association' })), caption };
}

export function attachReferenceTopics(topics: Record<string, HelpTopic>, schemas: InspectorSchema[]): void {
  for (const [id, reference] of Object.entries(BEHAVIOR_ELEMENT_REFERENCES)) {
    topics[`behavior-element-${id}`] = { title: reference.title, category: 'Behavior Elements', description: reference.body, content: reference.body,
      sections: [{ id: 'use', title: 'Meaning and use', body: reference.body }, { id: 'example', title: 'Worked example', body: reference.example }], related: [reference.chapter, 'diagram-reference'] };
    const chapter = topics[reference.chapter];
    if (chapter) chapter.related = [...new Set([...(chapter.related ?? []), `behavior-element-${id}`])];
  }
  for (const definition of getSupportedElementKinds()) {
    const kind = definition.metaclass, topic = topics[`sysml-element-${kind}`], example = ELEMENT_EXAMPLES[kind];
    if (!topic || !example) continue;
    const owners = Object.entries(OWNERSHIP_MATRIX).filter(([, kinds]) => kinds.includes(kind)).map(([owner]) => owner);
    const schema = schemas.find(item => item.metaclass === kind);
    const properties: HelpSection = { id: 'properties', title: 'Properties', body: 'The table follows the current inspector schema. Values shown are reference-sample values, not universal creation defaults. Additional owned-feature fields are edited in the applicable feature editor.',
      table: { columns: ['Property', 'Type / access', 'Reference value', 'Meaning'], rows: (schema?.fields ?? []).map(field => [field.label,
        `${field.valueType} / ${field.mode}`, field.value == null || field.value === '' ? 'Unset in reference sample' : field.options?.find(option => option.value === field.value)?.label ?? (typeof field.value === 'string' && field.value.startsWith('help-') ? field.value === 'help-owner' ? 'Example package' : field.value.slice(5) : typeof field.value === 'object' ? JSON.stringify(field.value) : String(field.value)),
        topics[`inspector-field-${field.key}`]?.content ?? field.readOnlyReason ?? 'Inspect the supported editor for this field.']) } };
    const supplements: HelpSection[] = [
      { id: 'context', title: 'Ownership and modeling context', body: `Modeling basis: ${definition.authority === 'OMG_SYSML_1_6' ? 'SysML 1.6' : definition.authority === 'UML_FOUNDATION' ? 'UML foundation' : 'ADIA extension'}. ${kind === 'Model' ? 'The Model is the fixed root of ownership.' : `Allowed owners: ${owners.join(', ') || 'use the supported contextual editor'}.`} Use an eligible owner in the Model Explorer; an unavailable action may indicate an incompatible context. A diagram presentation references the existing element.` },
      properties,
      { id: 'example', title: 'Worked example', body: example[2], diagram: schematic([example[1], example[0], definition.category === 'feature' ? 'Typed feature /\ncontaining definition' : 'Model view /\nrelated references'], 'Reference-context schematic. Plain lines describe context/references, not UML containment notation or executable signal wiring.') },
      { id: 'validation', title: 'Validation and related editors', body: 'Inspect the committed owner, type and relationship references after editing. Use the domain diagnostics for rejected commands and dangling references. Remove from Diagram removes a presentation; Delete from Model has semantic impact. Review the active editor for fields beyond the general inspector.' },
    ];
    topic.sections = [...(topic.sections ?? []), ...supplements];
    topic.sources = ['src/engine/sysml/capabilities/catalog.ts', 'src/engine/sysml/capabilities/ownershipPolicy.ts', 'src/features/sysml/inspectorSchema.ts'];
    topic.related = [...new Set([...(topic.related ?? []), 'diagram-reference', 'bdd-reference'])];
  }
  for (const [kind, example] of Object.entries(RELATION_EXAMPLES)) {
    const topic = topics[`sysml-relationship-${kind}`];
    if (!topic) continue;
    const schema = schemas.find(item => item.metaclass === kind);
    topic.sections = [...(topic.sections ?? []), { id: 'example', title: 'Worked example', body: example[2], diagram: schematic([example[0], example[1]], `Endpoint concept schematic for ${kind}; consult the editor and chapter for its actual arrowhead and endpoint notation.`, kind) },
      { id: 'properties', title: 'Endpoint properties', body: 'Direction, role and type compatibility are checked by the command gateway. The reference sample shows schema fields; choose actual existing endpoint identities in your model.', table: { columns: ['Property', 'Access', 'Meaning'], rows: (schema?.fields ?? []).map(field => [field.label, field.mode, topics[`inspector-field-${field.key}`]?.content ?? field.readOnlyReason ?? 'Review the relationship editor.']) } }];
    topic.related = [...new Set([...(topic.related ?? []), 'diagram-reference'])];
  }
  for (const [id, reference] of Object.entries(DIAGRAM_REFERENCES)) {
    const sections: HelpSection[] = [
      { id: 'workflow', title: 'Create and review', body: reference.steps },
      { id: 'symbols', title: 'Elements and connections', body: reference.overview, table: { columns: ['Element / connection', 'Meaning and use'], rows: reference.symbols } },
      { id: 'reference-example', title: 'Reference example', body: reference.example, diagram: schematic([reference.symbols[0][0], reference.symbols[1][0], 'Inspect references /\nreview diagnostics'], 'Conceptual reference workflow; use the chapter examples for concrete domain notation.') },
    ];
    if (topics[id]) {
      for (const section of sections) {
        const existing = topics[id].sections?.find(item => item.id === section.id);
        if (existing) { if (section.table) existing.table = section.table; }
        else (topics[id].sections ??= []).push(section);
      }
      topics[id].related = [...new Set([...(topics[id].related ?? []), ...reference.related, 'diagram-reference'])];
    } else topics[id] = { title: reference.title, category: 'Diagram Reference', description: reference.overview, content: reference.overview, sections, related: reference.related };
  }
  topics['diagram-reference'] = { title: 'Diagram reference', category: 'Getting Started', description: 'Choose the diagram or execution workspace that matches your engineering task.', content: 'Start with the model meaning: structural definitions, internal usages, requirements, behavioral descriptions, executable charts, directed control graphs or conserving physical networks. Each reference chapter explains its elements, connections, example and execution context.',
    sections: [{ id: 'choose', title: 'Choose a diagram', body: 'Open a related chapter below for its workflow, notation and worked examples.', table: { columns: ['Diagram / workspace', 'Use it for'], rows: Object.values(DIAGRAM_REFERENCES).map(reference => [reference.title, reference.overview]) } }], related: Object.keys(DIAGRAM_REFERENCES) };
  // Reuse reviewed concrete schematics in the dedicated structural chapters.
  for (const [id, sectionId] of [['bdd-reference', 'bdd'], ['ibd-reference', 'ibd'], ['requirements-reference', 'requirements']]) {
    const diagram = topics['model-browser']?.sections?.find(section => section.id === sectionId)?.diagram;
    const target = topics[id]?.sections?.find(section => section.id === 'reference-example');
    if (target && diagram) target.diagram = id === 'ibd-reference' ? { ...diagram, nodes: diagram.nodes.map(node => node.id === 'controller' ? { ...node, label: 'regulator: Regulator\nport in' } : node) } : diagram;
  }
}
